    local equipDojo = self:GetEquipDojo()
    local cost = self:GetUpgradeCost()
    -- if not GoodsUtils.CheckConsumeDataCondition(cost, 10) then
    --     return
    -- end

    for i, v in ipairs(cost) do
        local num = GoodsUtils.GetThingNo(v.goodsId)
        if num < checkInt(v.goodsNum) then
            print("v.goodsId", v.goodsId)
            GameUtils.Toast(localize("道具不足"))
            return
        end
        v.num = -(v.goodsNum)
    end
    CardProgressionMgr:RequestOverseaEquipmentStarUp({playerEquipmentId = equipDojo.id}, cost, Constants.UICultivateLevelUpFinishType.EquipLadderRise)
    self:CloseDialog()
end

