end

---刷新装备道具
function CardProgressionEquipmentLadderRiseDialog:RefreshEquipmentGoods()
    local equipDojo = clone(self:GetEquipDojo())
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local goodsVo = goodsConfMgr:GetGoodsVoById(equipDojo.equipmentId)
    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.BeforeGoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload({dojo = equipDojo, goodsId = equipDojo.equipmentId, isShowNo = false})
    end

    equipDojo.star = checkInt(equipDojo.star) + 1
    equipDojo.level = 0
    ---@type GoodNodeMB
    local mbEnv2 = CfUtils.GetLuaScr(self.AfterGoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv2 then
        mbEnv2:Reload({dojo = equipDojo, goodsId = equipDojo.equipmentId, isShowNo = false})
    end

    CfUtils.FillText(self.TxtEquipName, goodsVo.name)
end

---刷新属性
function CardProgressionEquipmentLadderRiseDialog:RefreshAttrs()
    local equipDojo = self:GetEquipDojo()

    local attrs = EquipUtils.PreviewLadderRiseAttrs(equipDojo)
    for index, value in ipairs(attrs) do
        ---@type CardProgressionEquipmentLadderRisePreviewAttrNode
        local env = self:GetSubAttrEnv(index)
        CfUtils.SetActive(env.controller.gameObject, true)
        if isNotNull(env) then
            env:RefreshUI(attrs[index], index, equipDojo)
        end
    end

    -- local node = self.ATKNumericalValue:Find("SubAttrNode1")
    -- self:RefreshAttrNodeState(equipDojo, node)
end

---刷新按钮
function CardProgressionEquipmentLadderRiseDialog:RefreshBtn()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo
    local equipLevelUpTimes = checkInt(playerDojo.equipLevelUpTimes)
    local limit = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentQuickUpgradeLimit))
    if equipLevelUpTimes >= limit then
        CfUtils.SetActive(self.Quick, true)
        CfUtils.SetActive(self.QuickCommonBtnConsumePop, false)
    else
        CfUtils.SetActive(self.Quick, false)
    end
end

