---刷新升级消耗
function CardProgressionEquipmentLadderRiseDialog:RefreshUpgradeCost()
    local cost = self:GetUpgradeCost()
    
    -- 处理金币消耗
    local goldNum = nil
    for i, v in ipairs(cost) do
        if checkInt(v.goodsId) == Constants.Currency.GoldId then
            goldNum = v.goodsNum
            table.remove(cost, i)
            break
        end 
    end
    if goldNum then
        CfUtils.SetActive(self.CommonBtnConsumePop, true)
        CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, Constants.Currency.GoldId, goldNum, false, false)
    else
        CfUtils.SetActive(self.CommonBtnConsumePop, false)
    end
    
    CfUtils.RefreshCommonGoodsListLight(self.CommonGoodsList, cost, false, false, true, true, true)
end

---关闭界面
function CardProgressionEquipmentLadderRiseDialog:CloseDialog()
    UIModule.CloseDialog(self.controller)
end

---获取EquipDojo
function CardProgressionEquipmentLadderRiseDialog:GetEquipDojo()
    return self._equipDojo
end

---获取升级消耗
function CardProgressionEquipmentLadderRiseDialog:GetUpgradeCost()
    local equipDojo = self:GetEquipDojo()
    local goodsVo = goodsConfMgr:GetGoodsVoById(equipDojo.equipmentId)
    local params = {
        quality = goodsVo.quality,
        star    = equipDojo.star + 1,
        level   = 0
    }
    local equipmentCNRVo = EquipUtils.GetEquipmentCNRVo(params)
    return parse_rewards(equipmentCNRVo.upstarItem, equipmentCNRVo.upstarNum)
    
end

function CardProgressionEquipmentLadderRiseDialog:GetSubAttrEnv(i)
    local env = self.attrNodeEnvs[i]
    if env == nil then
        local node
        if i == 1 then
            node = self.SubAttrNode1
        else
            node = self.ATKNumericalValue.gameObject:AddChild(self.SubAttrNode1.gameObject)
        end
        env = CfUtils.GetLuaScr(node, "Game.CardProgression.Equip.CardProgressionEquipmentLadderRisePreviewAttrNode")
        self.attrNodeEnvs[i] = env
    end
    return env
end
